window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-aff490c074c9c388"]={"versions": [{"id": "FIG-aff490c074c9c388", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-ECU-Konfigurationsartefakte (ECUC Meta-Model). Das Diagramm veranschaulicht die Kernbeziehungen zwischen Konfigurationswerten, Parameterdefinitionen, BSW-Implementierungsbeschreibungen und der aggregierenden Wertesammlung im Kontext des AUTOSAR-Templates-Frameworks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier zentrale Entitäten und ihre Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><strong>ECUCDescriptionTemplate::EcucValueCollection</strong>: Spezialisierung von <code>ARElement</code>. Dient als Einstiegspunkt für die Sammlung konkreter ECU-Konfigurationswerte. Aggregiert über die Assoziationsrolle <code>+ecucValue</code> mit Multiplizität <code>1..*</code> und dem Stereotyp <code>«atpVariation»</code> Instanzen von <code>EcucModuleConfigurationValues</code>.</li>\n<li><strong>ECUCDescriptionTemplate::EcucModuleConfigurationValues</strong>: Spezialisierung von <code>ARElement</code>. Enthält die konkreten Werte für ein konfiguriertes BSW- oder RTE-Modul.</li>\n<li>Attribute:</li>\n<li><code>+ ecucDefEdition: RevisionLabelString</code></li>\n<li><code>+ implementationConfigVariant: EcucConfigurationVariantEnum</code></li>\n<li>Ausgehende Beziehungen:</li>\n<li><code>+definition</code> (Multiplizität <code>1</code>): Gerichtet referenziert auf <code>EcucModuleDef</code>.</li>\n<li><code>+moduleDescription</code> (Multiplizität <code>0..1</code>): Gerichtet referenziert auf <code>BswImplementation::BswImplementation</code>.</li>\n<li><strong>ECUCParameterDefTemplate::EcucModuleDef</strong>: Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>EcucDefinitionElement</code>. Repräsentiert das Parameterschema (Moduldefinition) eines BSW-Moduls.</li>\n<li>Attribute:</li>\n<li><code>+ apiServicePrefix: CIdentifier [0..1]</code></li>\n<li><code>+ supportedConfigVariant: EcucConfigurationVariantEnum [0..*]</code></li>\n<li><strong>BswImplementation::BswImplementation</strong>: Spezialisierung von <code>Implementation</code>. Beschreibt die spezifische Software-Implementierung des BSW-Moduls.</li>\n<li>Attribute:</li>\n<li><code>+ arReleaseVersion: RevisionLabelString</code></li>\n<li><code>+ vendorApiInfix: Identifier [0..1]</code></li>\n<li>Ausgehende Beziehung:</li>\n<li><code>+vendorSpecificModuleDef</code> (Multiplizität <code>0..*</code>): Gerichtet referenziert auf <code>EcucModuleDef</code> zur Verknüpfung mit herstellerspezifischen Parametererweiterungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktions- oder Sequenzabläufe. Die Konfigurationskette bildet einen statischen Modellierungsfluss ab:</p>\n<ol class=\"fig-list\">\n<li><code>EcucValueCollection</code> bündelt variabilitätsfähig (<code>«atpVariation»</code>) mehrere Modulkonfigurationen (<code>EcucModuleConfigurationValues</code>).</li>\n<li>Jede <code>EcucModuleConfigurationValues</code> verweist zwingend (<code>1</code>) auf ihre Basisspezifikation (<code>EcucModuleDef</code>) und optional (<code>0..1</code>) auf die konkrete Code-Implementierung (<code>BswImplementation</code>).</li>\n<li>Eine <code>BswImplementation</code> kann wiederum herstellerspezifische Moduldefinitionen (<code>vendorSpecificModuleDef</code>) referenzieren.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Metamodell für AUTOSAR-ECU-Konfigurationsbeschreibungen (<code>.arxml</code>):</p>\n<ul class=\"fig-list\">\n<li>Die Multiplizität <code>1</code> an <code>+definition</code> verlangt, dass jede Modulkonfiguration exakt einer <code>EcucModuleDef</code> zugeordnet sein muss.</li>\n<li><code>«atpVariation»</code> an <code>+ecucValue</code> zeigt an, dass die Zusammenstellung der Modulkonfigurationswerte von Systemvariabilitäten (Variantenmanagement über Vorverarbeitungs- und Post-Build-Kriterien) abhängig sein kann.</li>\n<li>Konfigurationsgeneratoren müssen die Konsistenz zwischen den unterstützten Varianten (<code>supportedConfigVariant</code> in <code>EcucModuleDef</code>) und der tatsächlichen Konfigurationsvariante (<code>implementationConfigVariant</code> in <code>EcucModuleConfigurationValues</code>) validieren.</li>\n<li>Über <code>BswImplementation</code> wird die Nachverfolgbarkeit zur AUTOSAR-Releasespezifikation (<code>arReleaseVersion</code>) sowie herstellerspezifischen Modulschablonen sichergestellt.</li>\n</ul>"}, {"id": "FIG-69068b27b2fdd9b5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-ECU-Konfigurationsartefakte (ECUC Meta-Model). Das Diagramm veranschaulicht die Kernbeziehungen zwischen Konfigurationswerten, Parameterdefinitionen, BSW-Implementierungsbeschreibungen und der aggregierenden Wertesammlung im Kontext des AUTOSAR-Templates-Frameworks.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert vier zentrale Entitäten und ihre Assoziationen:</p>\n<ul class=\"fig-list\">\n<li><strong>EcucValueCollection</strong>: Spezialisierung von <code>ARElement</code>. Dient als Einstiegspunkt für die Sammlung konkreter ECU-Konfigurationswerte. Aggregiert über die Assoziationsrolle <code>+ecucValue</code> mit Multiplizität <code>1..*</code> und dem Stereotyp <code>«atpVariation»</code> Instanzen von <code>EcucModuleConfigurationValues</code>.</li>\n<li><strong>EcucModuleConfigurationValues</strong>: Spezialisierung von <code>ARElement</code>. Enthält die konkreten Werte für ein konfiguriertes BSW- oder RTE-Modul.</li>\n<li>Attribute:</li>\n<li><code>+ ecucDefEdition :RevisionLabelString</code></li>\n<li><code>+ implementationConfigVariant :EcucConfigurationVariantEnum</code></li>\n<li>Ausgehende Beziehungen:</li>\n<li><code>+definition</code> (Multiplizität <code>1</code>): Gerichtet referenziert auf <code>EcucModuleDef</code>.</li>\n<li><code>+moduleDescription</code> (Multiplizität <code>0..1</code>): Gerichtet referenziert auf <code>BswImplementation</code>.</li>\n<li><strong>EcucModuleDef</strong>: Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>EcucDefinitionElement</code>. Repräsentiert das Parameterschema (Moduldefinition) eines BSW-Moduls.</li>\n<li>Attribute:</li>\n<li><code>+ apiServicePrefix :CIdentifier [0..1]</code></li>\n<li><code>+ supportedConfigVariant :EcucConfigurationVariantEnum [0..*]</code></li>\n<li><strong>BswImplementation</strong>: Spezialisierung von <code>Implementation</code>. Beschreibt die spezifische Software-Implementierung des BSW-Moduls.</li>\n<li>Attribute:</li>\n<li><code>+ arReleaseVersion :RevisionLabelString</code></li>\n<li><code>+ vendorApiInfix :Identifier [0..1]</code></li>\n<li>Ausgehende Beziehung:</li>\n<li><code>+vendorSpecificModuleDef</code> (Multiplizität <code>0..*</code>): Gerichtet referenziert auf <code>EcucModuleDef</code> zur Verknüpfung mit herstellerspezifischen Parametererweiterungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktions- oder Sequenzabläufe. Die Konfigurationskette bildet einen statischen Modellierungsfluss ab:</p>\n<ol class=\"fig-list\">\n<li><code>EcucValueCollection</code> bündelt variabilitätsfähig (<code>«atpVariation»</code>) mehrere Modulkonfigurationen (<code>EcucModuleConfigurationValues</code>).</li>\n<li>Jede <code>EcucModuleConfigurationValues</code> verweist zwingend (<code>1</code>) auf ihre Basisspezifikation (<code>EcucModuleDef</code>) und optional (<code>0..1</code>) auf die konkrete Code-Implementierung (<code>BswImplementation</code>).</li>\n<li>Eine <code>BswImplementation</code> kann wiederum herstellerspezifische Moduldefinitionen (<code>vendorSpecificModuleDef</code>) referenzieren.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Metamodell für AUTOSAR-ECU-Konfigurationsbeschreibungen (<code>.arxml</code>):</p>\n<ul class=\"fig-list\">\n<li>Die Multiplizität <code>1</code> an <code>+definition</code> verlangt, dass jede Modulkonfiguration exakt einer <code>EcucModuleDef</code> zugeordnet sein muss.</li>\n<li><code>«atpVariation»</code> an <code>+ecucValue</code> zeigt an, dass die Zusammenstellung der Modulkonfigurationswerte von Systemvariabilitäten (Variantenmanagement über Vorverarbeitungs- und Post-Build-Kriterien) abhängig sein kann.</li>\n<li>Konfigurationsgeneratoren müssen die Konsistenz zwischen den unterstützten Varianten (<code>supportedConfigVariant</code> in <code>EcucModuleDef</code>) und der tatsächlichen Konfigurationsvariante (<code>implementationConfigVariant</code> in <code>EcucModuleConfigurationValues</code>) validieren.</li>\n<li>Über <code>BswImplementation</code> wird die Nachverfolgbarkeit zur AUTOSAR-Releasespezifikation (<code>arReleaseVersion</code>) sowie herstellerspezifischen Modulschablonen sichergestellt.</li>\n</ul>"}], "trans": [{"from": "FIG-aff490c074c9c388", "to": "FIG-69068b27b2fdd9b5", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Entfernung der Paket-Präfixe aus den Klassennamen der Metaklassen:</li>\n<li><code>ECUCDescriptionTemplate::EcucValueCollection</code> wurde zu <code>EcucValueCollection</code></li>\n<li><code>ECUCDescriptionTemplate::EcucModuleConfigurationValues</code> wurde zu <code>EcucModuleConfigurationValues</code></li>\n<li><code>ECUCParameterDefTemplate::EcucModuleDef</code> wurde zu <code>EcucModuleDef</code></li>\n<li><code>BswImplementation::BswImplementation</code> wurde zu <code>BswImplementation</code></li>\n<li>Typografische Bereinigung der Attributdeklarationen (Leerzeichen vor dem Doppelpunkt bei <code>:RevisionLabelString</code>, <code>:Identifier</code>, <code>:EcucConfigurationVariantEnum</code> und <code>:CIdentifier</code>).</li>\n</ul>"}]};
